import{_ as i,l as o,o as e,c as l,v as t,p as s,x as r,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"按需调页","description":"","frontmatter":{"title":"按需调页","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/demand-paging.md","filePath":"cs/demand-paging.md","lastUpdated":1789023840000}'),h={name:"cs/demand-paging.md"};function m(E,a,A,_,B,f){const n=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="按需调页" tabindex="-1">按需调页 <a class="header-anchor" href="#按需调页" aria-label="Permalink to &quot;按需调页&quot;">​</a></h1><div class="epigraph"><p>不必在运行前把程序全部装入内存；第一次访问某页时再为它分配物理页。</p><footer>—— 据 Denning, The Working Set Model for Program Behavior, CACM 1968；Silberschatz et al. 整理</footer></div><p><a href="/cs/brk-heap">上一课</a>画出合法虚区间，许多页此刻仍无物理页。<a href="/cs/paging-vm">分页</a>的缺页异常已经能进内核。<a href="/cs/load-dynlink">加载</a>若一次装入全部文本，启动慢且浪费。<a href="/cs/tlb-translate">TLB</a> 仍只缓存已填的翻译。缺口是<strong>按需</strong>：访问到再补页。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>进程虚空间可以远大于物理内存。若启动时为每页分配帧，机器跑不了几个进程。若永远不分配，第一次取指令就无翻译。缺口不是新的页表格式，而是策略：页表项先标无效；缺页时内核分配帧、必要时从可执行文件或交换区读入、填表、再执行那条指令。</p><p>本课不选哪一页被换出，那是下一课置换。这里假定「还有空闲帧」。</p><p><span class="marginnote">工作集：近期触碰的页集合。Denning 用它解释为何按需加上局部性后，驻留集可以远小于虚空间。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>用户访问 → MMU 走页表 → 无效 → 缺页陷入（组成课入口）→ 内核看是非法地址则杀进程或给信号，合法则分配帧、填内容、置有效与权限 → 返回用户，硬件重试指令。文本页内容来自文件；匿名页可先填零。预调（把相邻页一并装入）是可选优化，不改「第一次触及才必须正确」这条。</p>',9)),(e(),s(c,null,{default:r(()=>[p(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%AE%BF%E9%97%AE%E8%99%9A%E9%A1%B5%22%5D%20--%3E%20FAULT%5B%22%E7%BC%BA%E9%A1%B5%E9%99%B7%E5%85%A5%22%5D%0A%20%20FAULT%20--%3E%20ALLOC%5B%22%E5%88%86%E9%85%8D%E7%89%A9%E7%90%86%E5%B8%A7%22%5D%0A%20%20ALLOC%20--%3E%20FILL%5B%22%E5%A1%AB%E6%96%87%E4%BB%B6%E6%88%96%E9%9B%B6%E9%A1%B5%22%5D%0A%20%20FILL%20--%3E%20RETRY%5B%22%E9%87%8D%E8%AF%95%E6%8C%87%E4%BB%A4%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>按需把<a href="/cs/locality-principle">局部性</a>从 Cache 课接到 OS：只有工作集占物理内存。系统调用 <code>exec</code> 可以只建页表骨架，几乎不读磁盘，直到入口指令缺页。与运行时 GC 不同：GC 回收的是语言对象；调页回收的是帧——还没到回收，下一课才缺帧。</p><p>权限仍来自分页课：只读文本写了是保护错，不是「再调一页可写」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入倒排页表实现，不把巨型页当默认。也不把交换分区的槽位分配写完。网络文件系统上的按需读文件，语义仍是「缺页时填」，延迟更大而已。</p><p>指令重试要求精确异常：缺页的那条 load/store 不能已经写坏寄存器。组成课已经要求精确，本课直接用。</p><p>后课默认：合法访问可以在缺页时才占帧。帧不够时淘汰谁，下一课缺页与置换。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>页先无效，触及再分配并填内容。</li><li>工作集解释为何虚大于物仍可跑。</li><li>无空闲帧时的淘汰是下一课。</li><li>出处：Denning, <em>CACM</em> 1968；Silberschatz et al., <em>OSC</em>；Tanenbaum <em>MOS</em>。</li></ul>',9))])}const T=i(h,[["render",m]]);export{g as __pageData,T as default};
